 require(not(root/FOLDER).exists()and out.is_relative_to(private)and not out.exists(),'NEW catalog/private paths required');qualification=verify(root,private);primary=source_audit(root,cache);before={n:(root/n).read_bytes()for n in META};registry=predecessor(root,before);after,registry,coverage=transition(before,registry,read(root/ROLES)['roles']);previous=(root/DATA/'SHA256SUMS').read_bytes();rows=checksums(previous);require(len(rows)==900,'Predecessor checksum count changed');verify_sums(root,rows);out.mkdir();folder=root/FOLDER;folder.mkdir()
